WITH base AS (SELECT * FROM inventory WHERE product_id IN (1, 2, 5, 9) OR quantity < 144), summary AS (SELECT YEAR(last_restock) AS last_restock_year, product_id, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM base GROUP BY YEAR(last_restock), product_id) SELECT last_restock_year, product_id, stddev_quantity FROM summary WHERE stddev_quantity < 39 ORDER BY 1 DESC, product_id LIMIT 3
